window.VD=window.VD||{};window.VD["audi/a6-c7"]={"a6-c7-acc-distance-setting-in-mmi":"<p><strong>Purpose</strong>: to change the distance of the Adaptive Cruise Control (ACC) on the menu in Audi MMI 3G.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>13 – Regulation dist</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 7</strong> </em>then set the value to <strong>1</strong></p>\n<p><em>Restart MMI (MENU + CAR 10 sec).</em></p>\n<p><em>For the cruise control menu, press CAR then driver assistance then Adaptive cruise control, you can choose “Distance” 4 distance selection modes</em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7452-7b2530cd.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7166-a399eb74.webp\"/></figure>","a6-c7-activate-automatic-speed-selection-on-odb":"<p><strong>Purpose </strong>: displays automatic speed selection in D and S modes on the on-board display.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>02 – Auto Trans</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Then select <strong>“Single Gear Display”</strong> from the drop-down list</p>\n<p><em>Set value to </em><strong><em>“D on/S on</em></strong></p>","a6-c7-activate-battery-charge-status-in-mmi":"<p><strong>Purpose:</strong> Activates battery charge status in Audi MMI 3GP.  <br/></p>\n<p><em><strong>WARNING: </strong>You must have activated the Hidden Menu<a href=\"#/audi/a6-c7/a6-c7-activate-mmi-3gp-hidden-menu\">(Activate MMI 3GP hidden menu</a>).</em></p>\n<p><em>To launch the Hidden Menu press MENU + CAR (for 6s)</em></p>\n<p>car -&gt; carextdevicelist -&gt; battery -&gt; check box</p>\n<p>car -&gt; carmenuoperation -&gt; battery -&gt; select <strong>5</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_MMI3g_PLUS_Hidden_Menue_battery-5a0d0626.webp\"/></figure>\n<p>Restart MMI</p>\n<p><em>Press SETUP + Wheel + Top Right Button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/mmi3g_reset-cdd6298b.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_MMI_3G_PLUS_batterie-69d82b4b.webp\"/></figure>","a6-c7-activate-bluetooth-audio-streaming-a2dp-mmi-3gp":"<p><strong>Purpose</strong>: Enables Bluetooth streaming audio on the MMI 3G PLUS, so you can listen to music from your A2DP-compatible audio player.  </p>\n<p><em>ATTENTION: You must have activated the Hidden Menu (<a href=\"https://www.vag-coding.net/a6-c7-activate-mmi-3gp-hidden-menu/\">Activate hidden menu MMI </a><a href=\"https://www.vag-coding.net/a5-8t-facelift-activate-mmi-3gp-hidden-menu/\">3GP</a>)</em> and enabled Bluetooth (either by default or via the “Activate Bluetooth MMI 3GP” tutorial).  </p>\n<p>Press CAR + MENU (for 6s)  </p>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AMI BT [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ami_bt-8fa46d9c.webp\"/></figure>\n<p>bluetooth -&gt; Check <strong>A2DP Activation</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p-90e760bc.webp\"/></figure>\n<p>Restart MMI</p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p_v2-660aabbb.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p_v3-6ac58876.webp\"/></figure>","a6-c7-activate-daytime-running-lights-drl-on-mmi":"<p><strong>Purpose</strong>: to activate/deactivate the daytime running lights (DRL) on the MMI.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p>4 – Click on “Coding – 07” then “Long Coding Helper”.</p>\n<p><strong>5</strong> – Select Byte<strong> 3 </strong>:</p>\n<p>Bit<strong> 0 </strong>: Check<em> <strong>“Daytime Running Lights Adjustable via MMI/Car Menu”.</strong> </em> </p>","a6-c7-activate-door-mood-lighting-retrofit":"<p><strong>Purpose</strong>: to activate the ambient lighting retrofitted to the driver/passenger door and rear doors (retrofit). The ambient lighting retrofitted to the doors can therefore be dimmed via the MMI input (similar to floor lighting).   </p>\n<p>Mood lighting must be activated! ( see tutorial: <a href=\"#/audi/a6-c7/a6-c7-activate-mood-lighting\">Activate mood lighting</a> ) </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>42 – Electronic Door Control Module</strong></strong>“.</p>\n<p><strong>4</strong> – Click “ <strong>Encoding – 07</strong>,” then click<strong> “Long Coding Helper.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em><br/><em>Bit <strong>1</strong></em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>52</strong></strong><strong>– front passenger door electronics</strong>.”</p>\n<p><strong>4</strong> – Click “ <strong>Encoding – 07</strong>,” then click<strong> “Long Coding Helper.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em><br/><em>Bit <strong>1</strong></em></p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>62 – Left rear door electronics</strong></strong>“.</p>\n<p><strong>4</strong> – Click “ <strong>Encoding – 07</strong>,” then click<strong> “Long Coding Helper.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em><br/><em>Bit <strong>1</strong></em></p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “<strong><strong>72</strong> – Right Rear Door Electronics</strong>.”</p>\n<p><strong>4</strong> – Click “ <strong>Encoding – 07</strong>,” then click<strong> “Long Coding Helper.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em><br/><em>Bit <strong>1</strong></em></p>","a6-c7-activate-dvd-playback-while-driving-vim":"<p><strong>Purpose</strong>: Allows you to remove the MMI protection and continue watching a DVD or video while driving (Video in Motion).   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Step 1: Recovering the MMI 3GP serial number</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Advanced Ident -1A</strong>”.</p>\n<p>Retrieve serial number (if more than one, use the <strong>first</strong> one!)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a1_8x_mmi_plus_5f_seriennummer-PNG-12291981.webp\"/></figure>\n<p><strong>Step 2: Calculating the security code</strong></p>\n<p>Enter the serial number previously retrieved from the website (your choice, subject to availability):  </p>\n<p>–&gt; <a href=\"https://www.audienthusiasts.com/Articles_VIM.html\" rel=\"noopener\" target=\"_blank\">AUDIENTHUSIATS VIM</a></p>\n<p>–&gt; <a href=\"https://www.bestcarmods.com/vim/\" rel=\"noopener\" target=\"_blank\">BESTCARMODS VIM</a></p>\n<p>The site will display your security code.<br/><em>An alternative security code is also generated.</em></p>\n<p><strong>Step 3: Enter security code</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Secure access -16</strong>”.</p>\n<p>Enter security code <br/><em>(Use alternative security code if first code does not work)</em></p>\n<p><strong>Step 4: Removing the protection</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation -10</strong>”.</p>\n<p><strong>5 – </strong>Select Channel <strong>48</strong> </p>\n<p><em>Set value to <strong>255</strong></em></p>\n<p><strong>Step 5: Restart the MMI</strong></p>\n<p>Simultaneously press MENU + Wheel + Top right button</p>","a6-c7-activate-gearshift-recommendation":"<p><strong>Purpose:</strong> Activates the gearshift recommendation. The gearshift recommendation is then displayed in the lower section of the ODB.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>“<br/>Then check Bit<strong>“5</strong>“.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7102-675f485c.webp\"/></figure>","a6-c7-activate-mmi-3gp-hidden-menu":"<p><strong>Purpose</strong>: Enables the hidden green menu (green menu, hidden menu, test mode, engineer mode) in the Audi MMI 3G PLUS. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>5F – Electrical Information</strong></strong>“.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 6</strong> </em>and set the value to <strong>1</strong></p>\n<p><strong>Facelift Line:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“S12345</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong><strong>Developer Mode</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>Enabled</strong>.”</p>\n<p><em>No need to restart the MMI.</em></p>\n<p><em><em>To open the Hidden Menu, press MENU + CAR (simultaneously for 6 seconds), or press the CAR button first.</em></em></p>\n<p><em>For Facelift: <br/>The hidden green menu can be accessed in a different way on newer models/as follows:<br/>NAV/MAP (or CAR) and RADIO<br/>For the red engineering menu, it’s:<br/>NAV/MAP (or CAR) and MEDIA<br/><strong>Note:</strong> First press NAV/MAP (or CAR), then press the second button (MEDIA/RADIO). Hold both buttons down for about five seconds, then release them. The menu should open.  </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/a7_mmi_plus-bb5ba729.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_navigation_plus_mmi3g_hidden_menue-ae4ebd5e.webp\"/></figure>\n<p><strong>Note:</strong> <strong>Never</strong> select the “Bootloader” option!</p>\n<p><strong><a href=\"#/t/access-the-audi-red-engineering-menu\">–&gt; To access the Audi Red Engineering menu</a></strong></p>\n<p><a href=\"#/t/enabling-the-hidden-menu-for-audi-mmi-3g-and-3g\"><strong>–&gt; Enable the hidden MMI 3G/3G+ menu without VCDS or OBDeleven</strong></a></p>","a6-c7-activate-mmi-3gp-speed-limit-display":"<p><strong>Purpose</strong>: Activates the speed limit display (traffic sign display) for the MMI 3G PLUS navigation system. The speed limit display appears in the navigation zone or on the navigation map, even without a camera system.   </p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong></p>\n<p><em>To activate the MMI hidden menu (Green Menu) : <a href=\"#/audi/a6-c7/a6-c7-activate-mmi-3gp-hidden-menu\">Activate MMI 3GP Hidden Menu</a></em></p>\n<p>Press <strong>CAR + MENU</strong> for 6 sec to bring up the hidden menu.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/a7_mmi_plus-bb5ba729.webp\"/></figure>\n<p>Select diagnostics/coding/internal_modules_1+2/<br/><br/>Deactivate the “<strong>VZA (Off)</strong>” input (traffic sign display).</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_A6_4G_STG5F_MMIPLUS_3GP-75ac55ca.webp\"/></figure>\n<p><strong>Restart MMI</strong></p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_reset-f3d493fd.webp\"/></figure>\n<p>After restart, the : Speed display (speed display) must be activated in the navigation area under Settings.<br/>Speed limit information is then available and displayed on the navigation map view.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_A6_4G_STG5F_MMIPLUS_3GP2-b300156b.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_A6_4G_STG5F_MMIPLUS_3GP3-c778dd0f.webp\"/></figure>","a6-c7-activate-mmi-rmc-hidden-menu":"<p><strong>Purpose</strong>: Activates the green hidden menu (green menu, hidden menu, testmode, engineer mode) in Audi MMI RMC.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 5</strong> </em>and set the value to <strong>1</strong></p>\n<p><em><em>No need to restart the MMI.</em></em></p>\n<p><em>To open the Hidden Menu, press MENU + CAR (for 6 seconds)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/mmi3g-217db9e1.webp\"/></figure>\n<p><strong><a href=\"#/t/access-the-audi-red-engineering-menu\">–&gt; To access the Audi Red Engineering menu</a></strong></p>","a6-c7-activate-mood-lighting":"<p><strong>Purpose</strong>: to activate foot lighting while driving. Management can then be controlled via the MMI. This means you can decide for yourself how bright the footwell lighting should be. In the negative position, the footwell lighting can also be switched off again, so that it is not visible if it becomes disruptive.     </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<h4><strong>Activation of hidden menu for MMI 3g (pre-lifting model) and activation of floor lighting</strong></h4>\n<p><strong>The hidden menu must be activated</strong> (See: <a href=\"https://www.vag-coding.fr/audi/a6-c7/a6-c7-activer-menu-cache-mmi-3gp/\" rel=\"noopener\" target=\"_blank\">Activate hidden menu MMI 3GP</a> ) <br/><br/><strong>Line 1:</strong> <strong>Activate mood lighting</strong><br/><br/> 3 – Click on ” <strong>Select”</strong> then click on “Select”.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong> “Long Coding Helper”</strong>.</p>\n<p><strong>5</strong> – Select <em>Byte <strong>16</strong>: </em><br/><em>Bit <strong>6</strong>: Tick “Interior/Ambiance Lighting Adaptation active”.</em></p>\n<p><strong>Line 2: Activate the MMI menu</strong></p>\n<p>Launch the Hidden Menu by pressing MENU + CAR (for 6s)</p>\n<p>car -&gt; carmenuoperation -&gt; interior light -&gt; select “5”.</p>\n<p>Press “Return</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/interior_light_hidden_menu_mmi3g-8680e758.webp\"/></figure>\n<p>  car -&gt; cardevicelist -&gt; interior light -&gt; check box</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/interior_light_hidden_menu_mmi3g1-9f0f03ff.webp\"/></figure>\n<p>  car -&gt; carbusassignment -&gt; Interior light -&gt; Select [CAN Komfort] 1/9</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_facelift_hidden_menu_car_carbusassignme-331aee89.webp\"/></figure>\n<p>Reboot the MMI by pressing MENU + Wheel + Top Right Button.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_reset-f3d493fd.webp\"/></figure>\n<p><strong>Line 3: Ambient lighting control from MMI</strong></p>\n<p><strong>How it works:</strong></p>\n<p><em>Ambient lighting</em><br/><em> – is permanently activated when the light control switch is in OFF position.</em><br/><em> – switches on/off automatically when the headlamp switch is in AUTO position.</em><br/><em> – will never light up to 100% (even when maximum lighting is selected).</em><br/><em> – lights up to 100% when doors are opened.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_facelift_setup_fussraumbeleuchtung-1639c23f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_facelift_dimmung_fussraumbeleuchtung-2d9373cb.webp\"/></figure>\n<hr/>\n<h4>Activate MMI MIB2 (facelift model) to control foot lighting – mood lighting</h4>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F – Informat. electr. </strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Then select <strong>“List of vehicle functions BAP Interior lighting 0x08”</strong> from the drop-down list.</p>\n<p><strong>6</strong> – Set value to<strong>“active</strong></p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F – Informat. electr. </strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Then select <strong>“list of vehicle functions BAP interior lighting 0x08 msg bus”</strong> from the drop-down list.</p>\n<p><strong>6</strong> – Set the value to<strong>“terminal 15</strong>”.</p>\n<p><strong>Line 3:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F – Informat. electr. </strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Then select <strong>“vehicle menu display ambient lighting operating menu”</strong> from the drop-down list.</p>\n<p><strong>6</strong> – Set value to<strong>“active</strong></p>\n<p><strong>Line 4:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F – Informat. electr. </strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Then select <strong>“Display vehicle menu operation, ambient lighting above high threshold</strong> <strong>”</strong> from the drop-down list.</p>\n<p><strong>6</strong> – Set value to<strong>“active</strong><br/> <br/> </p>\n<p>Reset MMI<br/>(Simultaneously press and hold function button -1- (Menu), confirmation button -2- and navigation button -3-. The MMI then switches off and restarts. Takes approx. 60 seconds)  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_reset-f3d493fd.webp\"/></figure>","a6-c7-activate-reversing-camera-retrofit":"<p><strong>Purpose:</strong> To activate the reversing camera after it has been installed on the MMI RMC or 3GP. <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong><br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>“.<br/><br/> 4 – Select <strong>“Installation List”</strong><br/><br/> 5 – Tick:<strong>“6C – Rear View Camera</strong>” in the list</p>\n<p><strong>6</strong> – Save coding</p>\n<p><strong>Line 2:</strong><br/><br/> 3 – Click on<strong>“Select”</strong> then click on<strong>“6C – Rear view camera</strong>“.<br/><br/> 4 – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/> 5 – <strong>Coding</strong>:  </p>\n<p>1030015 = Automatic hitch, with APS+.</p>\n<p>1000015 = RVC only</p>\n<p>1020015 = APS+, without automatic coupler</p>\n<p>1010015 = Automatic hitch, without APS+.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/>For MMI RMC :<br/><strong>6</strong> – Select byte <strong>6</strong><br/>Then set bit <strong>2</strong></p>\n<p>For MMI 3GP: <br/> 6 – Select byte <strong>7</strong><br/>Then set bit <strong>1</strong></p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Car Function List BAP Gen2 – VPS_0x0B</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the<strong>“active</strong>” value.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong><strong>Car Function List BAP Gen2 – VPS_0x0B_msg_bus</strong></strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value “<strong><strong>Terminal 15</strong></strong>“</p>\n<p><strong>Restart MMI</strong></p>\n<p><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   </p>\n<p><br/>The 2 pins of the reversing camera are used in the 12-pin quadlock (blue). Usable cable set: Part no. 000 979 009 E <br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>","a6-c7-activate-traffic-online-function":"<p><strong>Purpose</strong>: Activates the Traffic Online function for the Audi A6 4G and the integrated navigation system PLUS MMI (3GP). After activation, traffic disruptions are compared online via the SIM card’s Internet connection. The SIM slot is therefore required for successful activation.    </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 69</strong> </em>then set bit 15 (+32768)</p>\n<p>Resetting the MMI<br/>(Simultaneously press and hold the menu button -1-, the confirmation button -2- (middle) and the navigation button -3- (top right). The MMI then switches off and restarts. Takes approx. 60 seconds)  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_reset-f3d493fd.webp\"/></figure>","a6-c7-activate-trailer-coupling-retrofit":"<p><strong>Purpose:</strong> Enables the installation of a retrofit trailer hitch (trailer/towbar retrofit).  </p>\n<p><em>Please note! For Facelift model. Adaptation in motor control unit 01 is not accepted for some models. In this case, the coding can be ignored. Control units that are not installed can also be ignored. Please note that certain coding steps must be carried out according to the part numbers installed (camera).       </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Capture-decran-2024-01-09-215831-4f89678c.webp\"/></figure>\n<p><strong>Warning!! Depending on the modules you have installed, there are up to 12 coding lines to complete here; most ECUs require a long coding process with a “trailer” that must be enabled!  </strong><br/><br/><strong>Proceed :</strong><br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Select <strong>“Installation List”</strong><br/><br/><strong>5</strong> – Check the box next to “<strong>69 – Trailer</strong>” in the list</p>\n<p><strong>6</strong> – Save coding</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailergateway-3cb3c873.webp\"/></figure>\n<p><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“01 – Motor</strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>05</strong>“<br/>. Then check bit “<strong>4</strong>“: “<strong>Trailer installed</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailermoteur-fdaad0ca.webp\"/></figure>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong>“.</p>\n<p><em>For power plants <strong>with</strong> coding:</em><br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>“<br/><br/><strong>5</strong> – Select byte “<strong>01</strong>“<br/>Then, in the “<strong>Bit 0-7</strong>” drop-down menu, select “<strong>01 Trailer Connector Diagnosis active</strong>“.</p>\n<p><strong><em>Or</em></strong> Byte<strong>“01</strong>” check <strong>Bit 1</strong><strong>“Trailer Hitch Control Module Installed</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailercentrelec-0a9e9b3c.webp\"/></figure>\n<p><em>For power plants <strong>without </strong>coding :</em></p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Networking trailer connection device</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“built in”</strong> and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“24990</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“trailer stabilization</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>Active</strong>” and then confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter code<strong>“71679</strong>” (optional code)<br/><br/><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – Select byte<strong>“03</strong>”<br/>Then check Bit<strong> 0-1</strong> “01 Trailer Hitch installed (manually removable)”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailerpark-212dd6b1.webp\"/></figure>\n<p><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 – Auto Dist. Reg. </strong>“.<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>14117</strong>” or “<strong>20103</strong>“<br/><br/><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – Select byte<strong>“02</strong>” (camera 5Q0) or<strong>“03</strong>” (camera 2Q0/3Q0)<br/>Then check Bit<strong> 3</strong> “Trailer Recognition Control Module installed”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailerdist-da789d91.webp\"/></figure>\n<p><br/><br/><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>34 – Correct. Assiet. </strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select the “<strong>00</strong>” byte<br/>Then set bit <strong>7</strong> (“trailer, 0 = not installed / 1 = installed”)<br/><br/><br/><strong>Line 8:</strong></p>\n<p><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>3C – Lane Change</strong>.”<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“02</strong>” (camera 5Q0) or<strong>“00</strong>” (camera 2Q0/3Q0)<br/>Then check Bit <strong>4-7</strong> “10 or 20 ECU for draw bar, with ECU for draw bar”.<br/><br/><br/><br/><strong>Line 9:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>6C – Rearview Camera</strong>.”<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>04</strong>“<br/>Then set bit <strong>0</strong> (“equipment_ahk, installed”)<br/><br/><br/><strong>Line 10:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>6D – Trunk Electrical System </strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>01</strong>“<br/>Then set bit <strong>7</strong> (“trailer, 0 = not installed / 1 = installed”)<br/><br/><strong>Line 11:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Front, Sensors, Driver Assistance   </strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.</p>\n<p><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“</p>\n<p><strong>6</strong> – <em>Choose the line according to your camera reference!</em></p>\n<p>Select byte<strong>“16</strong>” (Camera 5Q0)</p>\n<p>Then check bit <strong>0-7</strong> “01 trailer_control_module, installed”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailera5-685c17e4.webp\"/></figure>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“11</strong>” (Camera 3Q0)</p>\n<p>Then set bit<strong> 0 ( </strong>“AAG, 0 = not_coded / 1 = coded”)</p>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“05</strong>” (Camera 2Q0)</p>\n<p>Then set bit <strong>4</strong> (“AAG, 0 = not_coded / 1 = coded”)</p>\n<p><strong>Line 12:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>69 – Trailer</strong></strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“01</strong>”<br/>Then check Bit <strong>0-3</strong> “01 Diagnosis of the line to the socket, active”.</p>\n<p>Select byte<strong>“03</strong>”<br/>Then check Bit<strong> 0-3</strong> “01 Terminal 30 output (pin 9 socket), activated”.</p>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“04</strong>”<br/>Then check Bit<strong> 0-7</strong> “02 Terminal 30 output switched (pin 10) Trailer connected”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailer69-acbfa990.webp\"/></figure>","a6-c7-add-sensitivity-menu-for-active-lane-assist":"<p><strong>Purpose</strong>: to add a menu for setting Active Lane Assist sensitivity in the MMI if the vehicle is equipped.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“8E – Image Processing</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Menu for time of assisted steering”</strong> from the drop-down list.</p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<p>Restart MMI</p>","a6-c7-audi-sound-system-volume-control":"<p><strong>Purpose</strong>: to adjust the volume of the engine sound (Audi Sound System – Soundaktor) inside the car. To mute the sound, use value: 0.   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><br/> 3 – Click on ” <strong>Select</strong> “, then click on “Select”. <strong><strong><strong>C0 – Aktuator</strong></strong></strong> ” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><strong>“Actuator volume for motor noise generation</strong>”.</p>\n<p>  Select your sound percentage (between 0 and 100)</p>","a6-c7-automatic-activation-of-electric-handbrake":"<p class=\"empty\">No procedure text was published on the source page.</p>","a6-c7-automatic-deactivation-of-unbuckled-electric-handbrake":"<p><strong>Purpose:</strong> Allows automatic deactivation of the electric handbrake on start-up without having to fasten the seatbelt.  </p>\n<p><strong>Only for vehicles with automatic gearbox</strong>.<br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“53-Station brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“78713</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Seat belt buckle detection”</strong> from the drop-down list. </p>\n<p><em>Set value to </em><strong>“<em>not active</em></strong></p>","a6-c7-automatic-folding-of-mirrors":"<p><strong>Purpose:</strong> automatic folding of mirrors when vehicle is locked, with menu added to MMI.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>52 – Passenger Door</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>04</strong>: </em><br/><em>Bit <strong>6</strong>: Tick “Comfort Mirror Folding active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4F0-959-793-R_Module52_Byte4-921dde8a.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>42 – Driver’s door</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>04</strong>: </em><br/><em>Bit <strong>6</strong>: Tick “Comfort Mirror Folding active”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4F0-959-793-R_Module52_Byte4-921dde8a.webp\"/></figure>\n<p><strong>Line 3:</strong></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong> then click on “<strong>46 – Central Conv.</strong></p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Choose <em>Byte<strong> 07 </strong>: </em><br/><em>Bit <strong>7</strong>: Check “Folding Mirrors installed”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/4H0-907-064-CN_Module46_Byte7-eea19d21.webp\"/></figure>","a6-c7-automatic-headlight-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_auswahl-steuergerate-rls-wws-bord-c6f10e6e.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_bordnetz_rls_autobahnlicht_regenl-c0c525c9.webp\"/></figure>","a6-c7-change-mmi-3gp-start-logo":"<p><strong>Purpose</strong>: to change the Splash Screen of the MMI 3G PLUS.  </p>\n<p><em>For a custom logo see tuto: A6 (C7) – MMI 3G/3GP custom start logo</em></p>\n<p><strong>Proceed :</strong> </p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong> </p>\n<p><em>To activate the MMI hidden menu (Green Menu) : <a href=\"https://www.vag-coding.net/a6-c7-activate-mmi-3gp-hidden-menu/\">Activate MMI 3GP Hidden Menu</a></em></p>\n<p><strong>Step 1: Change the start logo in the hidden menu</strong></p>\n<p>Press <strong>CAR + SETUP</strong> for 6 sec to bring up the hidden menu.</p>\n<p>car -&gt; carcodingvehicle -&gt; Select No Of Screen</p>\n<p><em>Select the desired display:</em><br/><em><br/>0 -&gt;  Standard display<br/>1 -&gt;  Standard display<br/>2 -&gt;  A8<br/>3 -&gt;  S8<br/>4 -&gt;  W12<br/>5 -&gt;  A6<br/>6 -&gt;  S6<br/>7 -&gt;  RS6<br/>8 -&gt;  A6 allroad<br/>9 -&gt;  A7<br/>10 -&gt;  S7<br/>11 -&gt;  RS7<br/>12 -&gt;  A1<br/>13 -&gt;  S1<br/>14 -&gt;  Q3<br/>15 -&gt;  A4<br/>16 -&gt;  A4 allroad<br/>17 -&gt;  S4<br/>18 -&gt;  RS4<br/>19 -&gt;  A5<br/>20 -&gt;  S5<br/>21 -&gt;  RS5<br/>22 -&gt;  Q5<br/>23 -&gt;  Q5 Hybrid<br/>24 -&gt;  Q7<br/>25 -&gt;  Q7 Hybrid<br/>26 -&gt;  SQ5<br/>27 -&gt;  Standard display<br/>28 -&gt;  Standard display<br/>29 -&gt;  Standard display</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/splashscreenmmi3gp-6fcb5f6a.webp\"/></figure>\n<p><br/><strong>Step 2: Restart MMI</strong></p>\n<p>Simultaneously press SETUP or MENU (1) + Central knob (2) + Top right knob (3)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/redemarrermmi3g-18d07873.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RS6-99c35be3.webp\"/></figure>","a6-c7-change-mmi-rmc-start-logo":"<p><strong>Purpose</strong>: to change the Splash Screen of the MMI RMC.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>03</strong></p>\n<p><strong>standard</strong> logo:<br/>Bit <strong>0</strong> disabled<br/>Bit <strong>1</strong> disabled</p>\n<p><strong>S-Line</strong> logo:<br/>Bit <strong>0</strong> enabled<br/>Bit <strong>1</strong> disabled</p>\n<p><strong>S</strong> logo: <br/>Bit <strong>0</strong> disabled<br/>Bit <strong>1</strong> enabled</p>\n<p><strong>RS</strong> logo: <br/>Bit <strong>0</strong> enabled<br/>Bit <strong>1</strong> enabled</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6878-168e78a3.webp\"/></figure>","a6-c7-coming-home-leaving-home-duration-setting":"<p><strong>Purpose:</strong> Set the length of time the headlights remain on after the car is unlocked / locked (Coming Home / Leaving Home).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select</strong>” then click on “<strong>09 – Cent. Elect.</strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.  </p>\n<p><strong>5</strong> – Select “Coming Home Leaving Home Zeitdauer” <strong>channel </strong>(Duration)</p>\n<p><strong>6</strong> – Select duration from <strong>0 to 60 seconds</strong> (in 1 sec increments). (Default: 15 sec) </p>","a6-c7-coming-home-leaving-home-via-daytime-running-lights-drl":"<p><strong>Purpose</strong>: to activate the Coming Home / Leaving Home (CH/LH) function via the daytime running lights (DRL).  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong> .”</p>\n<p><strong>4</strong> – Click “ <strong>Encoding – 07</strong>,” then click<strong> “Long Coding Helper.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>6 : </strong> </em> </p>\n<p>Disable <em>Bit<strong> 4</strong> </em> </p>","a6-c7-corner-lights-activation":"<p><strong>Purpose</strong>: to switch on the fog lamp on the side where the steering wheel is turned.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Choose <em>Byte <strong>0</strong>: <br/>Bit<strong> 1</strong>: This is a hidden bit, replace the 0 with a 1 in Binary</em><br/><em>Bit <strong>2</strong>: This is a hidden bit, replace the 0 with a 1 in Binary</em></p>\n<p>Then <em>Byte <strong>4</strong>: <br/>Bit <strong>0</strong>: Check “Cornering Light via Fog Lights (depending on Sterring Angle)”.</em></p>","a6-c7-deactivate-door-open-alarm-with-contact":"<p><strong>Purpose:</strong> to deactivate the alarm which is triggered when the door is opened and the contact is in position P.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“16017</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <em><strong>Canal 98</strong>: </em> </p>\n<p><em>Set value to </em><strong><em>“0</em>”</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calculateur-46_Adaptation-Canal_98-b7b82f42.webp\"/></figure>\n<p><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select <em>Byte <strong>15</strong>: </em> </p>\n<p>Modify Binary value (save original coding)</p>\n<p>Phase 1 with binary: <br/>With initial value: 00000000 (00)<br/>New value: 00000101 (05)</p>\n<p>Phase 1 and Facelift: <br/>With initial value: 01000111 (47)<br/>New value: 01001111 (4F)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calculateur-46_Octet-15_nouvelle_valeur-219f66a3.webp\"/></figure>","a6-c7-deactivate-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> to deactivate automatic activation of the rear windshield wiper during reversing when the front windshield wipers are operating. (A6 Avant)   </p>\n<p><strong>Procedure:</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong></p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>4</strong> – Click on ” <strong>Adaptation – 10</strong>” .</p>\n<p>5 – Select <strong>Channel 19</strong> from the drop-down list</p>\n<p>To deactivate, select value <strong>0</strong></p>","a6-c7-deactivate-activate-electric-handbrake-for-rear-brake-pad-change":"<p><strong>Purpose:</strong> to deactivate/activate the electric handbrake in maintenance mode in order to change/replace the rear brake pad/disc linings. (EPB reset / Lining change mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/>To begin, set the gear lever to P and remove the electric handbrake on the button. Check that there are no faults/errors before starting basic setup.<br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“53 – Parking Brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start trim change mode.</strong>”<br/><br/><strong>6</strong> – Click on<strong>“Go</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/plaquettearriere-1024x629-2b32f223.webp\"/></figure>\n<p><br/><br/>A fault message will appear on your ODB indicating “<strong>Parking brake fault</strong>”, but this is normal and should be ignored<br/><br/> 7 – Wait for<strong>“Procedure complete</strong>” to be displayed<br/><br/> 8 – Once finished, return to the program until it closes<br/><br/> 9 – Switch off the vehicle’s ignition, then disconnect the VAG-COM cable<br/><br/><strong>10</strong> – <strong>Change the linings on both sides!</strong><br/><br/><br/></p>\n<p><strong>To reactivate the electric handbrake :</strong><br/><br/><br/><strong>11</strong> – With engine off and ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>12</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>13</strong> – Click on<strong>“Select”</strong> then click on<strong>“53 – Parking Brake</strong>”.<br/><br/><strong>14</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>15</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“End trim change mode.</strong>”<br/><br/><strong>16</strong> – Click on<strong>“Go</strong>”.<br/><br/><strong>17</strong> – Wait for<strong>“Procedure complete</strong>” display</p>","a6-c7-delete-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte <strong>0</strong>:<br/>Bit <strong>2-4</strong>: select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<p><strong><em>OR</em></strong></p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Deactivate</strong> <strong>Seat belt warning”</strong> / <strong>“</strong> <strong>Désactiver l’avertissement de ceinture”.</strong> <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select<strong>“Oui</strong>” /<strong>“Yes”</strong> and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8U0_920_940_Module17_Adaptation_desactivate_seat_b-77d3b532.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","a6-c7-disable-motor-cut-out-switch-on-door-opening":"<p><strong>Purpose</strong>: to deactivate the engine/ignition switch when the driver’s door is opened with the gear selector in position P and the seatbelt fastened.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>46 – Central Conv.</strong>” . 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>14</strong>: </em><br/><em>Bit <strong>3</strong>: This is a hidden bit, so the value must be modified directly in binary (replace 0 by 1, e.g.<strong>00011111)</strong>.</em></p>","a6-c7-disable-nav-phone-warning-messages-when-entering-while-driving":"<p><strong>Purpose</strong>: to suppress navigation and telephone warning messages on the MMI when entering data while driving.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on ” <strong>Adaptation – 10</strong>“.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 2 and 3</strong> </em>then set the value to <strong>250</strong>.</p>","a6-c7-disable-start-stop":"<p><strong>Purpose:</strong> To configure Start&amp;Stop operation. <br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20113</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”<strong>.</strong></p>\n<p><strong>6 –</strong> Choose<strong><em> </em>Channel 34</strong></p>\n<p><em>Enter new value according to desired options</em><br/><em>–<strong>4</strong> Start&amp;Stop disabled by default</em><br/><em><strong>+32</strong> Start&amp;Stop status stored before ignition switch-off</em><br/><em><strong>+64</strong> Reverse button light (on when Start&amp;Stop enabled)</em></p>","a6-c7-display-travel-mode-on-mmi":"<p><strong>Purpose</strong>: to display travel mode on the MMI.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 4 </strong>:</p>\n<p>Bit<strong> 6</strong>: Check<em> <strong>“Tourist Mode Adjustable via MMI/Car Menu”.</strong> </em> </p>","a6-c7-electric-tailgate-closure-with-remote-control":"<p><strong>Purpose: </strong>to close the electric tailgate with the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong>6D – Elect. safe </strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“12345</strong>“.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Activation using rear lid opening button in remote key-Tap fonction for closing”</strong> from the drop-down list . </p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7N0-959-107_Module6D_Adaptation_Remote_key-Tap_fun-1faa5c43.webp\"/></figure>","a6-c7-electric-tailgate-lock-with-button":"<p><strong>Purpose </strong>: to close the electric tailgate using the button on the driver’s door.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>6D – Elect. safe </strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“12345</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Activation using rear lid remote unlocking switch-Tap function for closing”</strong> from the drop-down list.</p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7N0-959-107_Module6D_Adaptation_Remote_unlocking_s-5c034a61.webp\"/></figure>","a6-c7-enable-mmi-3gp-cd-dvd-ripping":"<p><strong>Purpose</strong>: Activates CD/DVD extraction in the DVD player. Allows you to import / copy all CD/DVD / SD card content to the MMI 3G PLUS jukebox (hard disk).   </p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong></p>\n<p><em><em>To activate the MMI hidden menu (Green Menu) :</em> <a href=\"#/audi/a6-c7/a6-c7-activate-mmi-3gp-hidden-menu\">Activate MMI 3GP hidden menu</a></em></p>\n<p>Press <strong>CAR + SETUP</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnose -&gt; settings -&gt; import_multimedia -&gt; Tick <strong>Ripping</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi3g_plus_hidden_menu_cd-ripping-cbf13d3b.webp\"/></figure>\n<p><strong>Restart MMI</strong></p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/import_ripping_mmi3g_vagcoding-af2ca0fd.webp\"/></figure>","a6-c7-enable-mmi-3gp-wifi-streaming":"<p><strong>Purpose</strong>: Allows you to activate Wifi WLAN (hot spot) on the MMI 3G PLUS and listen to music from your audio player (iOS or Android) using the “Audi Music Stream” app.  </p>\n<p><em>WARNING: You must have activated the Hidden Menu<a href=\"https://www.vag-coding.net/a6-c7-activate-mmi-3gp-hidden-menu/\">(Activate MMI </a><a href=\"https://www.vag-coding.net/a5-8t-facelift-activate-mmi-3gp-hidden-menu/\">3GP</a>hidden menu ).</em> </p>\n<p>Press CAR + MENU (for 6s)  </p>\n<p>diagnose -&gt; settings -&gt; wlan_settings -&gt; Check <strong>WLAN activation</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_wlan_settings-469fc399.webp\"/></figure>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AUX [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_ami_bt-fdaa8044.webp\"/></figure>\n<p>Restart MMI</p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_wlan_settingsv1-1f55118b.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_wlan_settingsv2-9a607dcb.webp\"/></figure>\n<p>After the reboot, new menu items are available in the MMI under Phone and Media.<br/>WLAN parameters can be changed here, e.g. SSID, password, etc.</p>\n<p>The smartphone can now be connected via WLAN and the “Audi Music Stream” application can be launched.<br/>Under Media, you select the WLAN device as the source, e.g. “my iPhone”, and can then use the MMI to navigate the smartphone’s directory structure and select music files for playback.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_music_stream-577x1024-8dc123f4.webp\"/></figure>","a6-c7-flash-mode-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“46- Central Conv.</strong></p>\n<p>4 – Click on “Coding – 07” then “Long Coding Helper”.</p>\n<p><strong>5</strong> – <em>Select Byte <strong>8</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flashing via Turn Lights active” (to activate the turn signals)</em><br/><em>Bit <strong>1: </strong> Check “Emergency Brake Flashing via Brake Lights active” (to activate the brake lights)</em></p>","a6-c7-headlamp-washer-settings":"<p><strong>Purpose:</strong> to set the delay time before the headlamp washer emerges / the duration of the headlamp washer spray / the number of activations.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (Headlamp washer activation time) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 25</strong>: </em> </p>\n<p><em>Set value to </em><strong><em>“</em>8000”</strong> or value of your choice (default: 2000 ms)  </p>\n<p><strong>Line 2 (Headlamp washer spray duration) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 06</strong>: </em> </p>\n<p><em>adjust value accordingly (in ms)</em></p>\n<p><strong>Line 3 <strong>(Number of activations before headlamp washer) :</strong></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 26</strong>: </em><br/><em>adjust the value for the number of times the headlamp washer must be switched on manually before activation.</em></p>","a6-c7-high-beam-assist-settings":"<p><strong>Purpose</strong>: Allows you to adjust the speed thresholds for activating and deactivating the high-beam assist feature.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<h4><strong>Adjust high beam assistant activation speed threshold :</strong></h4>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>A5 – Front Camera</strong></strong>” or “<strong>20 – High Beam Assistant</strong>.”  </p>\n<p><strong>4</strong> – Click <strong>“Security Access – 16</strong>,” then enter the code “ <strong>20103</strong>”</p>\n<p><strong>5</strong> – Click <strong>“Adaptation –</strong> 10”</p>\n<p><strong>6 – </strong> Select Channel <em>:</em> “<em>Activation speed for the high-beam assistant</em>” or <em>“</em><em>Aktivierungsgeschwindigkeit für Fernlichtassistent”</em><br/></p>\n<p>Adjust value accordingly<br/>Default: 57 km/h</p>\n<h4><strong>Adjusting the high beam assistant deactivation speed threshold :</strong></h4>\n<p><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>A5 – Front Camera</strong></strong>” or “<strong>20 – High Beam Assistant</strong>.”  </p>\n<p><strong>4</strong> – Click <strong>“Security Access – 16</strong>,” then enter the code “ <strong>20103</strong>”</p>\n<p><strong>5</strong> – Click <strong>“Adaptation –</strong> 10”</p>\n<p><strong>6 – </strong> Select Channel <em>:</em> <em>“Speed threshold for high-beam recommendation”</em> or <em>“Geschwindigkeitsschwelle für Fernlichtempfehlung”</em><br/></p>\n<p>Adjust value accordingly<br/>Default: 27 km/h</p>","a6-c7-lock-unlock-confirmation-beeps":"<p><strong>Purpose</strong>: Enables vehicle lock/unlock confirmation with beeps.  </p>\n<p><strong>The vehicle must be equipped with the factory-installed alarm</strong>.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em> </p>\n<p><em>Bit <strong>2</strong>: Check “Anti-Theft System: Horn Confirmation Active”</em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <em><strong>Canal 63</strong>: </em> </p>\n<p><em>Add <strong>04</strong> to the value  </em></p>","a6-c7-lower-passenger-mirror-when-reversing":"<p><strong>Purpose:</strong> automatically lowers the passenger mirror when reversing.  </p>\n<p>The mirror adjustment knob must be in position<strong>“R”</strong> for the passenger mirror to lower automatically.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“4</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Reserve Gear Mirror Dipping active</strong>”<br/>and Bit<strong>“3</strong>”:<strong>“Position Memory for Reserve Gear Mirror Dipping active</strong>”<em>(if available</em>).<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-Abaisser-le-retroviseur-passager-lors-de-la-9710a97c.webp\"/></figure>","a6-c7-lowering-the-pneumatic-chassis":"<p><strong>Purpose:</strong> Allows you to lower the air suspension for a lowered look.  </p>\n<p>Select “<strong>Auto</strong>” mode via the MMI (it must not be set to Dynamic, Comfort, or any other mode…). Make sure the car is on level ground. Close the doors; if any doors open during this process, the procedure will be interrupted. Make sure the car is not in towing or tire-change mode. If necessary, shift the car into<strong>“Neutral”</strong> and release the parking brake (Remember that you’re supposed to be on level ground, so your A6/S6, A7/S7, C7/4G, or A8 D4 won’t move).</p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “ <strong><strong>34 – Level Control</strong></strong>.”</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>,” and note the four values labeled as:</p>\n<p>“<strong>Body height, front wheel well edge G”</strong></p>\n<p>“<strong>Body Height, Rear Wheel Well Edge G”</strong></p>\n<p><strong>“Body Height, Front Right Wheel Well Edge”</strong></p>\n<p>“<strong>Body Height, Rear Wheel Well Edge D”</strong></p>\n<p><strong>6</strong> – Take the values you wrote down above, and add the desired dimensions in millimeters (mm) to each value, carefully noting them on a sheet of paper…</p>\n<p>Example of an adjustment for a 15mm drop in the front and an 11mm drop in the rear:</p>\n<ul>\n<li>Front Left: <strong>392.80–&gt; 407.80</strong></li>\n<li>Before Right: <strong>388.40–&gt; 403.40</strong></li>\n<li>Left Rear: <strong>391.30–&gt; –402.30</strong></li>\n<li>Right Rear: <strong>385.60–&gt; –396.60</strong></li>\n</ul>\n<p>Please note that, as far as I understand, Audi allows for a lowering of 17 mm at the front and 13 mm at the rear. You can lower it further if you wish, but if you lower it just a little more, it will affect other parts of the system, such as the cameras, adaptive cruise control, etc., so be careful. </p>\n<p><strong>7</strong> – Press <strong>“BACK</strong>,” then go to<strong>“04 – Basic Settings</strong>”<br/><br/>IMPORTANT: Whatever you do, do not select<strong>“Reset All Adaptations”</strong>—it doesn’t work and will require a visit to the dealership.<br/><br/><strong></strong> 8 – Select<strong>“Activate Roll Correction</strong>,” click<strong>“Go!</strong>”, wait for it to finish (it should only take a second or two, until it says “Not Active”), and then press <strong>“Stop</strong>.”</p>\n<p><strong>9</strong> – Select “<strong>Clear Leveling Control Calibration</strong>,” click “<strong>Go!</strong>,” wait for the process to finish, and you’ll see an error message on the central display (OBD) of your instrument cluster that reads ” <strong>Air Suspension Malfunction </strong>” along with a small yellow car icon (illustration) featuring a two-way arrow in the center of the car (illustration). Don’t worry—this is normal. You’ll see “Not Active” displayed in VCDS, and then press <strong>“Stop</strong>.”</p>\n<p><strong>10</strong> – Select “<strong>Approach Reference Level</strong>,” then click “<strong>Go!</strong>” This step will take about a minute, and your car will rise and lower during the process (you’ll hear some whistling sounds). Wait for it to finish until “Inactive” appears, then press <strong>“Stop</strong>,” followed by <strong>“End, Back</strong>.”</p>\n<p><strong>11</strong> – Go to “<strong>10 – Adaptation</strong>” on the previous screen.</p>\n<p><strong>12</strong> – Next, you’ll need to enter the new values you defined in Step <strong>4</strong> into your documents for the various heights.</p>\n<p>“<strong>Body height, front wheel well edge G”</strong></p>\n<p>“<strong>Body Height, Rear Wheel Well Edge G”</strong></p>\n<p><strong>“Body Height, Front Right Wheel Well Edge”</strong></p>\n<p>“<strong>Body Height, Rear Wheel Well Edge D”</strong></p>\n<p>Select them one by one to enter the new value you have determined, click “<strong>Save</strong>,” and then repeat the process for the other three wheel heights.</p>\n<p>Every time you enter a value, you should see a message indicating that it has been accepted.</p>\n<p><strong>13</strong> – After completing the adjustments for all 4 wheels, select “<strong>Back</strong>” and return to “<strong>04 – Basic Settings</strong>” again.</p>\n<p><strong>14</strong> – In the basic settings, select “<strong>Calibrate Pitch Control</strong>” and press “<strong>Go!</strong>“; you’ll need to wait a few seconds. Wait until “Inactive” appears, then press ” <strong>Stop</strong>.”</p>\n<p>If you get an error during this step, either you missed a step described above, or something didn’t go as planned.</p>\n<p><strong>15</strong> – Select “<strong>Enable Trim Correction</strong>,” click “<strong>Go!</strong>,” wait a few seconds until “Inactive” appears, and then press ” <strong>Stop</strong>,” followed by ” <strong>Done, Back</strong>.”</p>\n<p><strong>16</strong> – You’re done. Go to “<strong>02 – Trouble Codes”</strong>and have fun clearing the error codes.</p>\n<p>Get out of the car and watch; wait a moment, and it will lower just as you wanted!</p>\n<p><em>If you want to make another adjustment, completely disregard the changes you made previously, because this one<strong>does not build on the </strong>previous ones—it completely overwrites them.</em></p>\n<p><em>For example, if you decreased the value by 5 mm the first time to 392.80, refer to step 2 of this tutorial and repeat the steps.</em></p>\n<p><em>So you’ve changed it to 397.80. You want a total lowering of 15 mm. You’ll then enter 407.80 the second time, to lower it by an additional 10 mm during the second adjustment, which will bring you to a total of 5 + 10 = 15 mm.<br/>I’d like to remind you that a “visible” yet fairly safe lowering value is 17 mm in the front and 13 mm in the rear at the very most. Going any lower is strongly discouraged.   </em></p>","a6-c7-maintain-led-intensity-with-indicators":"<p><strong>Purpose</strong>: Maintains the brightness of the LEDs (DRLs) when the turn signals are on. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong> .”</p>\n<p><strong>4</strong> – Click “ <strong>Encoding – 07</strong>,” then click<strong> “Long Coding Helper.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>3 : </strong> </em> </p>\n<p><em>Bit<strong> 7</strong>: Uncheck “</em><strong><em>Daytime Running Lights inactive with Turn Signal (” Winking “) active</em></strong><em>”</em></p>","a6-c7-mmi-3g-3gp-customized-start-logo":"<p><strong>Purpose</strong>: To modify and/or customize the home screen logo (Custom Splash Screen) with a personalized image of the MMI 3G and 3GPLUS. <br/><br/>Start by downloading the script file: <a href=\"https://www.vag-coding.fr/download/MMI_3G_3GP_SplashScreen_VAG-Coding.fr.zip\" rel=\"noopener\" target=\"_blank\">MMI_3G_3GP_SplashScreen_VAG-Coding.en.zip</a></p>\n<p><strong>Proceed </strong>:</p>\n<ul>\n<li>Then extract the file you just downloaded: MMI 3G 3GP SplashScreen VAG-Coding.en.zip</li>\n<li>Go to the “splashscreens” folder and edit the “startup_generic.png” image if you wish. You can edit this image, modify it or import another image, to have your own startup logo (keep the same PNG format and image size 800×480) or an image found in the “samples” folder (copy it into the “splashscreens” folder with the name startup_generic.png. </li>\n<li>Copy the contents of the MMI_3G_3GP_SplashScreen folder to a FAT32-formatted SD card (max. 32GB).</li>\n<li>Start your AUDI and let the MMI boot up, it takes a few seconds.</li>\n<li>Disconnect your smartphone’s Bluetooth if there’s a link between it and the MMI, and remove all your SD cards (SD1 &amp; SD2)…</li>\n<li>Then insert the SD card you have prepared into slot SD1.</li>\n<li>You’ll see green text asking you to turn the large knob on your MMI central console, and the message will disappear.</li>\n<li>Wait a few moments. A new message will appear stating that all has gone well and that your image has been imported successfully. </li>\n<li>Restart the MMI using the button combination that corresponds to your AUDI.<br/>Example: Press SETUP or MENU (1) + Central knob (2) + Top right button (3) at the same time.</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/redemarrermmi3g-18d07873.webp\"/></figure>\n<p>If your new start-up screen does not appear when your MMI reboots, go to the green hidden menu<em> (to activate the hidden menu, follow the “Activate MMI 3G or 3GP hidden menu” tutorial).</em></p>\n<p>For <strong>MMI 3GP </strong>: Select in <strong>car </strong>-&gt;<strong> carcodingvehicle </strong>-&gt;<strong> Select n° screen </strong>-&gt;<strong> set cursor to 0</strong>, then restart your MMI.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/splashscreenmmi3gp-6fcb5f6a.webp\"/></figure>\n<p>For <strong>MMI 3G</strong>: <strong>car</strong> -&gt; <strong>carcodingvehicle</strong> -&gt; <strong>configuration line</strong> -&gt; <em><strong>[standard] 2/5</strong> (Standard home screen)</em> then restart your MMI.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6876-ad94c126.webp\"/></figure>\n<p>Your very own Splash Screen will appear!<br/>Many images are available in the zip file… both the original and modified ones.</p>\n<p><em>A problem?  </em>If the script doesn’t run the first time, try again. You’ve only copied the contents of the MMI_3G_3GP_SplashScreen folder? Do not copy the folder, just its contents!  <br/>For MMI 3G Basic: If your image does not appear or is truncated, resize the image to 400 by 240.</p>\n<hr/>\n<ul><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A1-cca1d214.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A1-quattro-d5c05d6b.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6-ec35ba13.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6-allroad-ecfb784b.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6-Hybrid-8b3bc272.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6L-da4efe88.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A7-0413e2db.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A8-b82aa2e7.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A8-Hybrid-bf48c947.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_Q3-f5806bdd.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_Q5-137fb9fc.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RS6-99c35be3.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RS7-973708ca.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RSQ3-82016453.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RSQ5-4b2a2aa7.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S1-8fca826d.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S6-ff017200.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S6-png_APR-b51955a9.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S6-APR-5b67cc13.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S7-1b8e075e.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S8-1a7397d6.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_Vierge-e6bcc4e4.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_W12-9cbddbdf.webp\"/></figure></li></ul><a></a><a></a><a></a>","a6-c7-mmi-3gp-bluetooth-activation":"<p><strong>Purpose</strong>: to activate Bluetooth with an Audi MMI 3G PLUS.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong></p>\n<p><em>To activate the MMI hidden menu (Green Menu) : <a href=\"https://www.vag-coding.net/a6-c7-activate-mmi-3gp-hidden-menu/\">Activate MMI 3GP Hidden Menu</a></em></p>\n<p><strong>Step 1: Activate Bluetooth in the hidden menu</strong></p>\n<p>Press <strong>CAR + MENU</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnostics  &gt;  settings  &gt;  tel_settings -&gt;  Select <strong>“HFP activation”</strong><br/>diagnose   &gt;  settings  &gt;  tel_settings -&gt;  Select <strong>“BT activation”</strong><br/>diagnostics   &gt;  settings  &gt;  tel_settings -&gt;  Select  <strong>“BT defaut visibility” to [auto] 1/3</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_tel_settings-af0d9718.webp\"/></figure>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AMI BT [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ami_bt-8fa46d9c.webp\"/></figure>\n<p><strong>Step 2: Restart MMI</strong></p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<p><br/><strong>Step 3: Bluetooth activation with VCDS</strong><br/><br/> 3 – Click on ” <strong>Select”</strong> and then click on ” “.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 17</strong> </em>then set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Module_5F_Adaptation_Channel17-d3fc3a63.webp\"/></figure>","a6-c7-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>","a6-c7-odb-start-up-logo":"<p><strong>Purpose</strong>: to change the start-up logo displayed on the ODB (On-Board Computer).  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>” . 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>9</strong>: </em> <br/><em>Bit 0-7: Select value according to display<br/>00 – Logo A6<br/>01 – Logo A7<br/>02 – Logo S6<br/>03 – Logo S7<br/>04 – Logo RS6<br/>05 – Logo RS7<br/>06 – Logo A6 allroad<br/>07 – Logo A6 hybrid<br/>08 – Logo A6<br/>09 – Logo A7</em></p>","a6-c7-oil-temperature-boost-via-lap-timer":"<p><strong>Purpose:</strong> to add oil temperature and turbo boost to the stopwatch on the ODB screen. (From mid-2012 for oil temperature)   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Lap Timer active</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>\n<p>Standard :</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/boosta81-1024x498-580bc444.webp\"/></figure>\n<p>Enabled (temperature and boost in lap timer) :</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/boosta82-1024x498-763a6ebe.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/boosta83-1024x498-634a9b9a.webp\"/></figure>","a6-c7-parking-aid-display-on-mmi":"<p><strong>Purpose</strong>: activates the display of reversing radars on the MMI, for vehicles with the Audi Parking System rear option only.  </p>\n<p><strong>Procedure:</strong> <br/> 1<strong>– </strong>Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2 </strong>– Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“76 – Parking Assistance</strong>.”</p>\n<p><strong>4</strong> – Click on ” <strong>Code 07</strong>.”</p>\n<p><strong>5</strong> – <em>Replace the second “0” (from the left) with a “2”.</em></p>\n<p><em>Ex: Replace “<strong>0001106</strong>” with “<strong>0201106</strong>”.</em></p>\n<p><em>Coding :</em><br/><em>0?xxxxx: Visual Display</em><br/><em>0 = without Visual Display on MMI</em><br/><em>2 = with Visual Display on MMI</em></p>","a6-c7-rear-daytime-running-lights-drl":"<p><strong>Purpose</strong>: Enables the use of the taillights as daytime running lights (Scandinavian DRL).</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “ <strong>Coding – 07.”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 2: </strong></p>\n<p>Bit <strong>7</strong>: Check <em>“<strong>Daytime running lights via Tails Lights active</strong>“</em> </p>","a6-c7-reprogramming-a-new-battery":"<p><strong>Purpose:</strong> to reprogram / recode the new battery of all its data after replacement.  <br/><br/><br/><strong>Watch out! Depending on your calculator, select 61 or 19</strong> <strong>(CAN or UDS)</strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<h2>61-Batterie Regul. CAN </h2>\n<p>This procedure concerns the replacement of the battery in vehicles using a separate battery management control module.<br/>Address 61: Regul Battery. Labels: 4F0-910-181.lbl Reference SW: 4F0 910 181 E HW: 4F0 915 181 A Component: ENERGIEMANAGER H12 0490 Subsystem 1 – Part No: 000 915 105 C Component: von VA0 2502160103 Coding: 303030393135313035432056413032353032313630313033 Shop N °: WSC 54332 321 22222 </p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“61 – Battery Regul. </strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose the <strong>battery (slave) classified n°1</strong><br/><br/><strong>6</strong> – In<strong>“Coding battery</strong>” :  </p>\n<ul>\n<li>Enter the new Battery Part number (10 or 11 digits).</li>\n<li>Enter the new battery serial number (10 digits).</li>\n<li>Select the new battery supplier.</li>\n</ul>\n<p>[OK]<br/>[! Do – it]<br/>[Close Controller, Go Back – 06]</p>\n<p>Your new battery should now be coded, and the battery control module should be aware of the new battery.</p>\n<hr/>\n<h2>19-CAN Gateway using CAN</h2>\n<p>This procedure concerns battery replacement in vehicles using a battery management control module which is a slave / subsystem of the CAN gateway.Address 19: CAN Gateway (J533) Labels: 8T0-907-468.clb Reference SW: 8T0 907 468 Q HW: 8T0 907 468 L Component: GW-EBM 5CAN-M H10 0095 Subsystem 1 – Part No SW: 8K0 915 181 B HW: 8K0 915 181 B Component: J367-BDM H04 0150</p>\n<p>Installation of a new battery requires use of the [Long Adaptation-0A function] under the 19-CAN-Gateway control module. . Follow the on-screen instructions to enter the part number, supplier, serial number and any long new value.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“19 – <strong>Gateway </strong>CAN</strong>”.<br/><br/> 4 – Click on<strong>“Long Adaptation-0A</strong>”.</p>\n<p><strong>5 </strong>– Select <strong>Channel 04</strong></p>\n<p>VCED will populate instructions in the form of a pop-up balloon with formatting. For example:Format: nnnnnnnnnnn XXX zzzzzzzzzz N = battery part number (11 digits) X = battery supplier (3 digits) Z = battery serial number (10 digits) </p>\n<p>[Add to log] Saving the original value in a log is strongly recommended.<br/>Enter the New Battery details in the new field value.</p>\n<ul>\n<li>Note, the new value must be 26 (alpha numeric) characters in total, including spaces! If in doubt, check the logbook for the original battery formatting details. </li>\n</ul>\n<p>[Test]<br/>[Save]<br/>The value has been accepted by the controller the new battery coding is complete<br/>[Done, Back]<br/>[Close Controller, Go Back – 06]</p>\n<hr/>\n<h2>19-CAN Gateway help (UDS / ODX)</h2>\n<p>This procedure concerns battery replacement in vehicles using a battery management control module which is a slave / subsystem of the CAN gateway.Address 19: CAN Gateway (J533) Labels: None Reference SW: 4G0 907 468 E HW: 4G0 907 468 A Component: J533 – Gateway H08 0213 ASAM Dataset: EV_GatewUDS 001025 Battery Monitoring Control Module: Subsystem 1 – Part No SW: 8×0 915 181 HW: 8×0 915 181 Component: J367-BDM H07 0140</p>\n<p>Installing a new battery requires the use of the [Adaptation-10 function] under the 19-CAN-Gateway control module. Use the drop-down menus to enter the part number, vendor, and serial number information located on the new battery. </p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Adaptation batterie-Capacité nominal de la batterie</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but towards the bottom<br/>of the page.<br/>On this menu, choose a nominal value indicated on your battery, e.g.<strong>“70Ah</strong>”.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Adaptation batterie-Fabriquant de batterie</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the corresponding brand:<br/>Ex: In the case of the VARTA E39, choose<strong>“VAO</strong>”.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Adaptation batterie-Numéro de série de la batterie</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, enter the corresponding serial number:<br/>Warning, insert only the <strong>last 10 digits</strong> of the serial number.</p>\n<p>The value has been accepted by the controller the new battery coding is complete<br/>[Done, Back]<br/>[Close Controller, Go Back – 06]</p>\n<hr/>\n<p><strong>Battery</strong></p>\n<p>The vehicle’s battery is housed in the engine compartment and protected by a battery tray. Battery size and design depend on engine version, equipment and national variant. Standard, EFB and AGM batteries are used.<br/>Vehicles with petrol engines and start/stop systems are fitted with EFB batteries, while vehicles with diesel engines and start/stop systems are fitted with AGM batteries.   Vehicles with stationary chauﬀage generally have an AGM battery.</p>\n<p><strong>EFB</strong></p>\n<p>An EFB (Enhanced Flooded Battery) is a reinforced wet battery. The positive plate inside the battery is coated with an additional polyester canvas. This gives the battery’s active mass additional support on the plate. The alternating cycle resistance of these batteries is superior to that of standard batteries. During charging, the EFB battery is treated like a standard battery.</p>\n<p><strong>AGM battery</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-agm-f4b81a74.webp\"/></figure>\n<p>In AGM batteries (short for Absorbent Glass Mat), the battery’s electrolyte is retained in a micro-porous glass mat. An AGM battery is not only even more resistant to alternating cycles than an EFB battery, but also watertight. When charging, follow the charger’s operating instructions and select the AGM battery program if necessary.</p>\n<p>In the case of AGM batteries, the automotive battery electrolyte is retained in a micro-porous glass mat. In addition to<br/>increased resistance to alternating cycles, an AGM battery is characterized by its good sealing properties. Waterproofing is of crucial importance<br/>, especially when the battery is installed in<br/>the passenger compartment. When charging, please follow the charger’s operating instructions and select the program for<br/>AGM battery, if applicable.</p>\n<p>Below we see the battery brand, serial number and manufacturer.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-124711ff.webp\"/></figure>","a6-c7-speed-of-radar-deactivation-or-reversing-camera":"<p><strong>Purpose </strong>: Selects the speed at which radar and/or reversing camera are deactivated.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>10 – Assistance stationn</strong>”.  <br/><br/><strong>4 – </strong>Click on <strong>“Adaptation – 10”</strong> </p>\n<p>5 – Select<strong> Channel 233 </strong>from the value list</p>\n<p><strong>6 –</strong> Choose a value between <strong>0 and 20 km/h</strong></p>","a6-c7-us-flasher":"<p><strong>Purpose</strong>: to activate US nightlights with turn signals, for xenon headlights only.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>09 – Power Control Unit</strong></strong> .”</p>\n<p><strong>4</strong> – Click on “ <strong>Coding – 07</strong>.”</p>\n<p><strong>5</strong> – Select Byte<strong> 10: </strong></p>\n<p>Bit <strong>0</strong>: Check <em>“</em> <strong>Turn signal active as side marker</strong> “</p>"};
